void go() {
  if ((int)path.size() == n) { res.push_back(path); return; }
  for (int i = 0; i < n; i++) {
    if (used[i]) continue;
    used[i] = 1; path.push_back(a[i]); go();
    path.pop_back(); used[i] = 0;
